def num_trees(n):
    dp = [0] * (n + 1)
    dp[0] = dp[1] = 1
    for k in range(2, n + 1):
        for i in range(1, k + 1):
            dp[k] += dp[i-1] * dp[k-i]
    return dp[n]

def num_trees(n):
    memo = {}
    def f(k):
        if k <= 1:
            return 1
        if k in memo:
            return memo[k]
        total = 0
        for i in range(1, k + 1):
            total += f(i - 1) * f(k - i)
        memo[k] = total
        return total
    return f(n)

