from collections import deque
def word_break(s, wordDict):
    words = set(wordDict); n = len(s)
    q = deque([0]); seen = {0}
    while q:
        i = q.popleft()
        if i == n: return True
        for w in words:
            if s.startswith(w, i) and i+len(w) not in seen:
                seen.add(i+len(w)); q.append(i+len(w))
    return False

