def max_profit(prices):
    n = len(prices)
    if n < 2:
        return 0
    hold = [-10**9] * n
    sold = [0] * n
    rest = [0] * n
    hold[0] = -prices[0]
    for i in range(1, n):
        hold[i] = max(hold[i-1], rest[i-1] - prices[i])
        sold[i] = hold[i-1] + prices[i]
        rest[i] = max(rest[i-1], sold[i-1])
    return max(sold[-1], rest[-1])

def coin_change(coins, amount):
    INF = 10**9
    dp = [INF]*(amount+1); dp[0] = 0
    for a in range(1, amount+1):
        for c in coins:
            if a >= c:
                dp[a] = min(dp[a], dp[a-c] + 1)
    return dp[amount] if dp[amount] != INF else -1

from collections import deque
def coin_change(coins, amount):
    q = deque([(0, 0)]); seen = {0}
    while q:
        a, d = q.popleft()
        if a == amount: return d
        for c in coins:
            na = a + c
            if na <= amount and na not in seen:
                seen.add(na); q.append((na, d+1))
    return -1 if amount else 0

def can_partition(nums):
    total = sum(nums)
    if total % 2:
        return False
    target = total // 2
    dp = [False] * (target + 1)
    dp[0] = True
    for x in nums:
        for s in range(target, x - 1, -1):
            if dp[s - x]:
                dp[s] = True
    return dp[target]

def can_partition(nums):
