def find_target_sum_ways(nums, target):
    total = sum(nums)
    if (total + target) % 2 or abs(target) > total:
        return 0
    s = (total + target) // 2
    dp = [0] * (s + 1)
    dp[0] = 1
    for x in nums:
        for i in range(s, x - 1, -1):
            dp[i] += dp[i - x]
    return dp[s]

def find_target_sum_ways(nums, target):
    offset = sum(nums)
    total = 2 * offset + 1
    dp = [0] * total
    dp[offset] = 1
    for x in nums:
        nxt = [0] * total
        for i, v in enumerate(dp):
            if v:
                nxt[i + x] += v
                nxt[i - x] += v
        dp = nxt
    return dp[offset + target]

